function scrollList(){if(SCROLLS)return SCROLLS;var by={},mobs=mobList();mobs.forEach(function(m){if(m.data)m.data.d.forEach(function(n){var x=n.match(SCROLL_RE);if(!x)return;var k=x[1]+' '+x[2],s=by[k]||(by[k]={part:x[1],stat:x[2],key:k,by:{}});var r=s.by[x[3]]||(s.by[x[3]]=[]);if(r.indexOf(m)<0)r.push(m);});});var ord=function(list,v){var i=list.indexOf(v);return i<0?99:i;};SCROLLS=Object.keys(by).map(function(k){return by[k];}).sort(function(a,b){return ord(SCROLL_PARTS,a.part)-ord(SCROLL_PARTS,b.part)||ord(SCROLL_STATS,a.stat)-ord(SCROLL_STATS,b.stat)||(a.key<b.key?-1:1);});return SCROLLS;}
